## Envoy + Java Bulkhead Implementation

```yaml
# Envoy Adaptive Concurrency + Route Header Tagging
http_filters:
  - name: envoy.filters.http.adaptive_concurrency
    typed_config:
      "@type": type.googleapis.com/envoy.extensions.filters.http.adaptive_concurrency.v3.AdaptiveConcurrency
      gradient_controller_config:
        sample_aggregate_percentile:
          value: 95
        concurrency_limit_params:
          max_concurrency_limit: 4000
        min_rtt_calc_params:
          interval: 60s
```

```java
// Spring / Resilience4j Bulkhead & Priority Admission Filter
@Component
public class PrioritySheddingFilter extends OncePerRequestFilter {
    private final Semaphore tier3Permits = new Semaphore(60, false);
    @Override
    protected void doFilterInternal(HttpServletRequest req, HttpServletResponse res, FilterChain chain)
            throws ServletException, IOException {
        int tier = classifyRoute(req.getRequestURI()); // 0=checkout, 3=telemetry
        if (tier == 3 && (systemLoadRatio() > 0.75 || !tier3Permits.tryAcquire())) {
            res.setStatus(429);
            res.setHeader("Retry-After", String.valueOf(20 + ThreadLocalRandom.current().nextInt(20)));
            return;
        }
        try { chain.doFilter(req, res); }
        finally { if (tier == 3) tier3Permits.release(); }
    }
}
```
